<script setup lang="ts">
import DecorationFrameworkContent from './DecorationFrameworkContent.vue'
import DecorationColorField from './DecorationColorField.vue'
import DecorationVisualPicker from './DecorationVisualPicker.vue'
import {frameworkAsset} from '../../../../api/src/core/decoration-framework.mjs'
import DecorationExtendedContent from './DecorationExtendedContent.vue'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import type {DecorationApplicationComponent,DecorationBlock,DecorationRoute,DecorationOptions} from '../../../../api/src/core/decoration-types'
import {decorationAppearance} from '../../../../api/src/core/decoration-contract.mjs'
import {galleryLayout,gallerySlotHint,changeGalleryLayout,decorationOptions} from '../../../../api/src/core/decoration-options.mjs'
import DecorationLayoutPicker from './DecorationLayoutPicker.vue'
import DecorationSettingRange from './DecorationSettingRange.vue'
import ConsolePagePathPicker from './ConsolePagePathPicker.vue'
import ImageSelectTile from './ImageSelectTile.vue'
const props=defineProps<{previousBlock?:DecorationBlock;applicationComponent?:DecorationApplicationComponent;collectionSources?:DecorationApplicationComponent[];disabled?:boolean;first?:boolean;materialEndpoint:string;routes:DecorationRoute[];imageUrl:(id:string)=>string}>()
const block=defineModel<DecorationBlock>({required:true})
const emit=defineEmits<{pick:[target:{itemId?:string;notice?:boolean}];checkpoint:[]}>()
const o=computed(()=>decorationOptions(block.value)),a=computed(()=>decorationAppearance(block.value))
function setO(key:keyof DecorationOptions,value:unknown){if(!props.disabled)block.value.options={...o.value,[key]:value}}
function setLayout(key:string){if(props.disabled)return;emit('checkpoint');block.value.appearance={...a.value};changeGalleryLayout(block.value,key);emit('checkpoint')}
function layout(value:string){if(!props.disabled)block.value.appearance={...a.value,layout:value}}
function add(){if(props.disabled||block.value.items.length>=(['links','collection'].includes(block.value.type)?50:10))return;block.value.items.push({id:crypto.randomUUID(),label:block.value.type==='notice'?'公告':'新入口',text:block.value.type==='notice'?'公告内容':undefined,imageId:null,target:'',enabled:true})}
function move(index:number,offset:number){if(props.disabled||index+offset<0||index+offset>=block.value.items.length)return;const [item]=block.value.items.splice(index,1);block.value.items.splice(index+offset,0,item!)}
function remove(index:number){if(!props.disabled)block.value.items.splice(index,1)}
let itemDrag=-1
function drop(index:number){if(props.disabled||itemDrag<0||itemDrag===index)return;const [item]=block.value.items.splice(itemDrag,1);block.value.items.splice(index,0,item!);itemDrag=-1}
const canMergeMembership=computed(()=>!!props.previousBlock?.enabled&&['membership','member-level','member-overview'].includes(props.previousBlock.type))
const modeOptions=[{value:'graphic',label:'图文'},{value:'image',label:'仅图片'},{value:'text',label:'仅文字'}]
</script>
<template><div class="block-content-panel">
<section v-if="block.type==='assets'" class="content-section">
 <label class="content-switch"><span>与上方会员权益合并</span><USwitch :model-value="o.assetMergeMembership" :disabled="disabled||!canMergeMembership&&!o.assetMergeMembership" aria-label="与上方会员权益合并" @update:model-value="setO('assetMergeMembership',$event)"/></label>
 <p class="text-xs leading-5 text-muted">{{canMergeMembership?'合并为一张卡片，共用账户资产的背景与圆角。会员权益和充值入口分别显示；关闭即可恢复分开显示。':'将启用的会员权益组件放在账户资产正上方，即可合并显示。'}}</p>
 <label class="content-switch"><span>显示标题</span><USwitch :model-value="o.assetTitle" :disabled="disabled" aria-label="显示资产标题" @update:model-value="setO('assetTitle',$event)"/></label>
 <template v-if="o.assetTitle"><UFormField label="标题"><ConsoleInput v-model="block.title" :maxlength="60" :disabled="disabled" placeholder="我的资产"/></UFormField><UFormField label="说明" hint="留空不显示"><ConsoleInput v-model="block.text" :maxlength="100" :disabled="disabled" placeholder="可填写简短的资产说明"/></UFormField></template>
 <h3>显示资产</h3>
 <label class="content-switch"><span>积分</span><USwitch :model-value="o.assetPoints" :disabled="disabled||o.assetPoints&&!o.assetBalance" aria-label="显示积分资产" @update:model-value="setO('assetPoints',$event)"/></label>
 <UFormField v-if="o.assetPoints" label="积分名称"><ConsoleInput :model-value="o.assetPointsLabel" :maxlength="20" :disabled="disabled" @update:model-value="setO('assetPointsLabel',$event)"/></UFormField>
 <label class="content-switch"><span>余额</span><USwitch :model-value="o.assetBalance" :disabled="disabled||o.assetBalance&&!o.assetPoints" aria-label="显示余额资产" @update:model-value="setO('assetBalance',$event)"/></label>
 <UFormField v-if="o.assetBalance" label="余额名称"><ConsoleInput :model-value="o.assetBalanceLabel" :maxlength="20" :disabled="disabled" @update:model-value="setO('assetBalanceLabel',$event)"/></UFormField>
</section><UFormField v-if="block.type==='links'" label="导航样式"><USelect :model-value="o.navStyle||'icons'" :items="[{label:'图标导航',value:'icons'},{label:'分类卡片',value:'tiles'}]" class="w-full" :disabled="disabled" @update:model-value="setO('navStyle',$event)"/></UFormField><section v-if="applicationComponent" class="grid gap-4"><UFormField label="标题"><ConsoleInput v-model="block.title" :maxlength="60" :disabled="disabled"/></UFormField><UFormField label="说明"><ConsoleInput v-model="block.text" :maxlength="500" :disabled="disabled"/></UFormField><UFormField label="更多入口"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField><p class="text-xs leading-relaxed text-muted">{{applicationComponent.description}}</p></section><section v-if="block.type==='collection'" class="content-section"><UFormField label="标题"><ConsoleInput v-model="block.title" :maxlength="60" :disabled="disabled"/></UFormField><UFormField label="说明"><ConsoleInput v-model="block.text" :maxlength="500" :disabled="disabled"/></UFormField><UFormField label="更多入口"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField><DecorationSettingRange label="显示数量" :model-value="o.collectionLimit??6" :min="1" :max="50" unit="个" :disabled="disabled" @update:model-value="setO('collectionLimit',$event)"/><UFormField label="数据来源"><USelect :model-value="o.collectionSource||'manual'" :items="[{label:'手动设置',value:'manual'},...(collectionSources||[]).map(source=>({label:source.label,value:source.type}))]" :disabled="disabled" class="w-full" @update:model-value="setO('collectionSource',$event==='manual'?'':$event)"/></UFormField><template v-if="!o.collectionSource"><div class="items-heading"><h3>卡片内容</h3><UButton color="neutral" variant="outline" size="sm" :disabled="disabled||block.items.length>=50" @click="add">添加卡片</UButton></div><article v-for="(item,index) in block.items" :key="item.id" class="decoration-item"><div class="item-actions"><span>卡片 {{index+1}}</span><UButton color="error" variant="ghost" size="xs" :disabled="disabled" @click="remove(index)">移除</UButton></div><UFormField label="名称"><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled"/></UFormField><UFormField label="描述"><ConsoleInput v-model="item.text" :maxlength="100" :disabled="disabled"/></UFormField><ImageSelectTile :src="item.imageId||item.builtin?imageUrl((item.imageId||item.builtin)!):null" label="卡片图片" :disabled="disabled" :removable="!!item.imageId" @select="$emit('pick',{itemId:item.id})" @remove="item.imageId=null"/><ConsolePagePathPicker v-model="item.target" :options="routes" allow-empty :disabled="disabled"/></article></template><p v-else class="text-xs leading-6 text-muted">{{collectionSources?.find(source=>source.type===o.collectionSource)?.description}}</p></section><DecorationFrameworkContent v-model="block" :disabled="disabled" :routes="routes" :image-url="imageUrl" @pick="$emit('pick',$event)"/><DecorationExtendedContent :key="block.id" v-model="block" :disabled="disabled" :routes="routes" :image-url="imageUrl" :material-endpoint="materialEndpoint"/>
<section v-if="block.type==='wechat-ad'" class="content-section"><h3>微信横幅广告</h3><p class="text-sm leading-6 text-muted">拖动组件调整位置。广告位读取「渠道管理 → 微信小程序 → 广告配置」中对应页面的横幅 ID。</p><p class="text-xs leading-5 text-muted">仅在微信小程序自主接入模式下显示；未配置或无可用广告时不占位。每页可添加一个，保存装修后生效。</p><UButton to="/admin/mini-program?tab=ads" color="neutral" variant="outline" icon="i-lucide-settings">广告配置</UButton></section>
<template v-if="block.type==='profile'"><section class="content-section"><h3>用户信息</h3><UFormField label="资料样式"><USelect :model-value="o.profileLayout" :items="[{value:'banner',label:'背景头部'},{value:'plain',label:'简洁横排'},{value:'center',label:'居中头像'}]" class="w-full" :disabled="disabled" @update:model-value="setO('profileLayout',$event)"/></UFormField><UFormField v-if="o.profileLayout==='banner'" label="背景图片"><ImageSelectTile :src="block.imageId?imageUrl(block.imageId):frameworkAsset('intro.webp')" label="会员信息背景图" :disabled="disabled" :removable="!!block.imageId" @select="$emit('pick',{})" @remove="block.imageId=null"/></UFormField><DecorationSettingRange v-if="o.profileLayout==='banner'" :model-value="o.profileHeight" label="背景区域高度" :min="170" :max="300" :disabled="disabled" @update:model-value="setO('profileHeight',$event)"/><p class="text-xs text-muted">头像、昵称和会员编号读取当前用户资料，预览展示示例内容。</p><label v-for="field in ([{key:'showAvatar',label:'显示头像'},{key:'showAccount',label:'显示账号'},{key:'showMemberNumber',label:'显示会员编号'}] as const)" :key="field.key" class="content-switch"><span>{{field.label}}</span><USwitch :model-value="o[field.key]" :disabled="disabled" @update:model-value="setO(field.key,$event)"/></label><UFormField label="点击跳转" :ui="{container:'mt-2'}"><ConsolePagePathPicker v-model="block.target" :options="routes" allow-empty :disabled="disabled"/></UFormField></section></template>
<template v-if="block.type==='gallery'"><DecorationLayoutPicker :model-value="galleryLayout(block)!.key" :disabled="disabled" @update:model-value="setLayout"/><div v-if="block.items.length!==galleryLayout(block)!.count" class="layout-repair"><span>当前布局需要 {{galleryLayout(block)!.count}} 张图片</span><UButton color="neutral" variant="outline" size="xs" :disabled="disabled" @click="setLayout(galleryLayout(block)!.key)">补齐图片位置</UButton></div></template>
<template v-if="block.type==='links'"><UFormField label="标题" hint="留空不显示" :ui="{container:'mt-2'}"><ConsoleInput v-model="block.title" :maxlength="60" :disabled="disabled" placeholder="例如：其他功能"/></UFormField><section v-if="o.navStyle==='tiles'" class="content-section"><h3>每行数量</h3><div class="content-choices"><button v-for="n in [1,2,3,4,5]" :key="n" type="button" :class="{active:a.columns===n}" :disabled="disabled" @click="block.appearance={...a,columns:n}">{{n}} 个</button></div></section><section v-if="!o.navStyle||o.navStyle==='icons'" class="content-section"><h3>导航布局</h3><div class="content-field"><span>排列方式</span><div class="content-choices"><button type="button" :class="{active:a.layout!=='list'}" :disabled="disabled" @click="layout('grid')">横向</button><button type="button" :class="{active:a.layout==='list'}" :disabled="disabled" @click="layout('list')">纵向</button></div></div><div class="content-field"><span>显示内容</span><div class="content-choices"><button v-for="m in modeOptions" :key="m.value" type="button" :class="{active:o.navMode===m.value}" :disabled="disabled" @click="setO('navMode',m.value)">{{m.label}}</button></div></div><template v-if="a.layout!=='list'"><div class="content-field"><span>行数</span><div class="content-choices"><button v-for="n in [1,2]" :key="n" type="button" :class="{active:o.navRows===n}" :disabled="disabled" @click="setO('navRows',n)">{{n===1?'单行':'多行'}}</button></div></div><div class="content-field"><span>展示方式</span><div class="content-choices"><button v-for="m in [{value:'fixed',label:'固定'},{value:'scroll',label:'横向滑动'},{value:'pages',label:'分页滑动'}]" :key="m.value" type="button" :class="{active:o.navDisplay===m.value}" :disabled="disabled" @click="setO('navDisplay',m.value)">{{m.label}}</button></div></div><div class="content-field"><span>每行数量</span><div class="content-choices"><button v-for="n in [1,2,3,4,5]" :key="n" type="button" :class="{active:a.columns===n}" :disabled="disabled" @click="block.appearance={...a,columns:n}">{{n}} 个</button></div></div></template></section></template>
<template v-if="block.type==='notice'"><section class="content-section"><h3>公告样式</h3><div class="content-choices"><button type="button" :class="{active:o.noticeMode==='text'}" :disabled="disabled" @click="setO('noticeMode','text')">文字标题</button><button type="button" :class="{active:o.noticeMode==='image'}" :disabled="disabled" @click="setO('noticeMode','image')">图片标题</button></div><UFormField v-if="o.noticeMode==='text'" label="公告标题"><ConsoleInput v-model="block.title" :maxlength="20" :disabled="disabled"/></UFormField><div v-else class="notice-presets"><button v-for="n in [1,2]" :key="n" type="button" :class="{active:o.noticePreset==='style'+n}" :disabled="disabled" @click="setO('noticePreset','style'+n)"><img :src="'/decoration/notice-'+n+'.png'" alt="公告标题样式"></button><ImageSelectTile :src="o.noticeImageId?imageUrl(o.noticeImageId):null" label="公告标题图片" :disabled="disabled" :removable="!!o.noticeImageId" @select="$emit('pick',{notice:true})" @remove="setO('noticeImageId',null);setO('noticePreset','style2')"/></div></section><section class="content-section"><h3>公告内容</h3><div class="content-field"><span>滚动方式</span><div class="content-choices"><button v-for="m in [{value:'vertical',label:'上下滚动'},{value:'horizontal',label:'横向滚动'}]" :key="m.value" type="button" :class="{active:o.noticeScroll===m.value}" :disabled="disabled" @click="setO('noticeScroll',m.value)">{{m.label}}</button></div></div><div class="content-field"><span>点击行为</span><div class="content-choices"><button v-for="m in [{value:'popup',label:'弹窗查看'},{value:'link',label:'链接跳转'}]" :key="m.value" type="button" :class="{active:o.noticeAction===m.value}" :disabled="disabled" @click="setO('noticeAction',m.value)">{{m.label}}</button></div></div><UFormField v-if="!block.items.length" label="公告内容"><UTextarea v-model="block.text" :rows="3" :maxlength="500" :disabled="disabled" class="w-full"/></UFormField></section></template>
<template v-if="['text','image','button'].includes(block.type)"><UFormField :label="block.type==='button'?'按钮文字':'标题'"><ConsoleInput v-model="block.title" :maxlength="60" :disabled="disabled"/></UFormField><UFormField v-if="block.type==='text'" label="正文 / 副标题"><UTextarea v-model="block.text" :rows="5" :maxlength="500" :disabled="disabled" class="w-full"/></UFormField></template>
<template v-if="block.type==='banner'"><label v-if="first" class="content-switch"><span>通屏显示</span><USwitch :model-value="o.sameScreen" :disabled="disabled" @update:model-value="setO('sameScreen',$event)"/></label><DecorationSettingRange v-model="block.height" label="图片高度" :min="40" :max="400" :disabled="disabled"/><label class="content-switch"><span>自动轮播</span><USwitch :model-value="o.autoplay" :disabled="disabled" @update:model-value="setO('autoplay',$event)"/></label><DecorationSettingRange label="切换间隔" :model-value="o.interval" :min="1000" :max="10000" :step="500" unit="ms" :disabled="disabled" @update:model-value="setO('interval',$event)"/><DecorationSettingRange label="切换速度" :model-value="o.duration" :min="100" :max="2000" :step="100" unit="ms" :disabled="disabled" @update:model-value="setO('duration',$event)"/></template>
<DecorationSettingRange v-if="block.type==='spacer'" v-model="block.height" label="留白高度" :min="0" :max="200" :disabled="disabled"/>
<template v-if="block.type==='image'"><UFormField label="图片"><ImageSelectTile :src="block.imageId?imageUrl(block.imageId):null" label="组件图片" :disabled="disabled" :removable="!!block.imageId" @select="$emit('pick',{})" @remove="block.imageId=null"/></UFormField></template>
<UFormField v-if="['image','button'].includes(block.type)" label="链接地址"><ConsolePagePathPicker v-model="block.target" :options="routes" :allow-empty="block.type!=='button'" :disabled="disabled"/></UFormField>
<template v-if="['links','banner','gallery','notice'].includes(block.type)"><div class="items-heading"><h3>{{block.type==='gallery'?'魔方图片':block.type==='banner'?'轮播图片':block.type==='notice'?'公告列表':'导航入口'}}</h3><UButton v-if="block.type!=='gallery'" color="neutral" variant="outline" size="sm" icon="i-lucide-plus" :disabled="disabled||block.items.length>=(block.type==='links'?50:10)" @click="add">{{block.type==='notice'?'添加公告':block.type==='banner'?'添加图片':'添加入口'}}</UButton></div><article v-for="(item,index) in block.items" :key="item.id" class="decoration-item" :draggable="!disabled&&block.type!=='gallery'" @dragstart="itemDrag=index;$event.dataTransfer?.setData('text/plain',String(index))" @dragover.prevent @drop.prevent="drop(index)"><div class="item-actions"><USwitch v-if="block.type!=='gallery'" :model-value="item.enabled!==false" :disabled="disabled" :aria-label="'显示入口 '+(index+1)" @update:model-value="item.enabled=$event"/><span v-else>图片 {{index+1}}<small class="slot-hint">建议比例 {{gallerySlotHint(block,index)}}</small></span><div><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-up" :aria-label="'上移入口 '+(index+1)" :disabled="disabled||index===0" @click="move(index,-1)"/><UButton color="neutral" variant="ghost" size="xs" icon="i-lucide-chevron-down" :aria-label="'下移入口 '+(index+1)" :disabled="disabled||index===block.items.length-1" @click="move(index,1)"/><UButton v-if="block.type!=='gallery'" color="error" variant="ghost" size="xs" :disabled="disabled" @click="remove(index)">移除</UButton></div></div>
<UFormField v-if="block.type==='notice'" label="公告内容" required><ConsoleInput v-model="item.text" :maxlength="40" :disabled="disabled" placeholder="填写公告内容"/></UFormField><UFormField v-else-if="block.type==='links'&&o.navMode!=='image'" label="入口名称" required><ConsoleInput v-model="item.label" :maxlength="20" :disabled="disabled" placeholder="填写入口名称"/></UFormField>
<UFormField v-if="block.type==='links'&&o.navStyle&&o.navStyle!=='icons'" label="副标题"><ConsoleInput v-model="item.text" :maxlength="100" :disabled="disabled"/></UFormField>
<template v-if="block.type==='links'&&o.navStyle==='tiles'"><DecorationColorField :model-value="item.background||'#f5f8fc'" label="背景颜色" :disabled="disabled" @update:model-value="item.background=$event"/><DecorationColorField v-if="item.backgroundEnd" v-model="item.backgroundEnd" label="渐变结束颜色" :disabled="disabled"/></template>
<DecorationVisualPicker v-if="block.type==='links'&&o.navMode!=='text'" v-model:image-id="item.imageId" v-model:icon="item.icon" :fallback-image="item.builtin?imageUrl(item.builtin):undefined" :label="item.label+'图标'" :image-url="imageUrl" :disabled="disabled" fallback-icon="layout-grid" @pick="$emit('pick',{itemId:item.id})"/><UFormField v-if="['banner','gallery'].includes(block.type)" label="图片" required><ImageSelectTile :src="item.imageId||item.builtin?imageUrl((item.imageId||item.builtin)!):null" :label="'入口 '+(index+1)+' 图片'" :disabled="disabled" :removable="!!item.imageId" @select="$emit('pick',{itemId:item.id})" @remove="item.imageId=null"/></UFormField>
<UFormField v-if="block.type!=='notice'||o.noticeAction==='link'" label="链接地址" :required="block.type==='links'"><ConsolePagePathPicker v-model="item.target" :options="routes" :allow-empty="block.type!=='links'" :disabled="disabled"/></UFormField></article></template>

</div></template>
<style scoped>.block-content-panel{display:grid;gap:22px}.content-section{display:grid;gap:18px}.content-section+.content-section{border-top:1px solid var(--ui-border);padding-top:20px}.content-section h3,.items-heading h3{font-size:13px;font-weight:500}.content-field{display:grid;gap:10px;font-size:12px}.content-choices{display:flex;gap:8px;flex-wrap:wrap}.content-choices button{border:1px solid var(--ui-border);border-radius:5px;padding:7px 12px;font-size:12px}.content-choices button.active{border-color:var(--ui-primary);color:var(--ui-primary);background:color-mix(in srgb,var(--ui-primary) 5%,var(--ui-bg))}.items-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}.decoration-item{border:1px solid var(--ui-border);border-radius:8px;padding:14px;display:grid;gap:14px;min-width:0}.item-actions{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px}.item-actions>div{display:flex;gap:3px}.content-switch{display:flex;justify-content:space-between;font-size:12px;align-items:center}.notice-presets{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.notice-presets>button{padding:8px;border:1px solid var(--ui-border);border-radius:6px}.notice-presets>button.active{border-color:var(--ui-primary)}.notice-presets>button img{max-width:110px;height:26px;object-fit:contain}.layout-repair{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;color:var(--ui-text-muted)}
.slot-hint{display:block;font-size:10px;color:var(--ui-text-muted);margin-top:4px}</style>
